import{_ as t,c as a,o as i,ag as r}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Communication_and_Security/HTTPS._Could_you_please_describe_advantages_and_disadvantages_of_this_protocol.md","filePath":"senior_growth/Communication_and_Security/HTTPS._Could_you_please_describe_advantages_and_disadvantages_of_this_protocol.md"}'),n={name:"senior_growth/Communication_and_Security/HTTPS._Could_you_please_describe_advantages_and_disadvantages_of_this_protocol.md"};function s(o,e,d,l,c,p){return i(),a("div",null,[...e[0]||(e[0]=[r('<h3 id="https-—-advantages-and-disadvantages" tabindex="-1">HTTPS — Advantages and Disadvantages <a class="header-anchor" href="#https-—-advantages-and-disadvantages" aria-label="Permalink to “HTTPS — Advantages and Disadvantages”">​</a></h3><h4 id="🔒-what-is-https" tabindex="-1">🔒 What is HTTPS? <a class="header-anchor" href="#🔒-what-is-https" aria-label="Permalink to “🔒 What is HTTPS?”">​</a></h4><p>HTTPS (Hypertext Transfer Protocol Secure) is HTTP protected by <strong>TLS</strong> (SSL is obsolete historical terminology), providing <strong>encryption</strong>, <strong>data integrity</strong>, and <strong>authentication</strong> between client and server. It ensures secure communication over the web.</p><hr><h3 id="✅-advantages" tabindex="-1">✅ <strong>Advantages</strong> <a class="header-anchor" href="#✅-advantages" aria-label="Permalink to “✅ Advantages”">​</a></h3><ol><li><p><strong>Data Encryption</strong></p><ul><li>Application content is encrypted between TLS endpoints; endpoint/CDN termination, logs and visible traffic metadata remain separate boundaries.</li><li>Protects sensitive data (passwords, tokens, personal info) from eavesdropping and man-in-the-middle attacks.</li></ul></li><li><p><strong>Data Integrity</strong></p><ul><li>Ensures that the data sent is not modified or corrupted during transfer.</li><li>TLS detects any tampering attempts.</li></ul></li><li><p><strong>Authentication</strong></p><ul><li>Certificates verify the identity of the server (and optionally client).</li><li>Certificate validation authenticates the requested endpoint identity under the trust policy; a malicious site can also have a valid certificate.</li></ul></li><li><p><strong>Improved SEO &amp; Trust</strong></p><ul><li>HTTPS is a deployment/security baseline; it does not guarantee a search rank or a trustworthy application.</li><li>Browsers label HTTP sites as “Not Secure”.</li></ul></li><li><p><strong>Enables Modern Features</strong></p><ul><li>Many platform APIs require a secure context, normally HTTPS; local-development exceptions, browser support and permission policies are separate requirements.</li></ul></li></ol><hr><h3 id="❌-disadvantages" tabindex="-1">❌ <strong>Disadvantages</strong> <a class="header-anchor" href="#❌-disadvantages" aria-label="Permalink to “❌ Disadvantages”">​</a></h3><ol><li><p><strong>Performance Overhead</strong></p><ul><li>Slight increase in CPU usage due to encryption/decryption.</li><li>Modern hardware and TLS session resumption reduce this impact.</li></ul></li><li><p><strong>Certificate Management</strong></p><ul><li>Certificates expire and must be renewed.</li><li>Misconfigured or expired certificates can break access.</li></ul></li><li><p><strong>Cost &amp; Complexity</strong></p><ul><li>Some certificates require payment.</li><li>Requires configuration (redirects, HSTS, mixed content handling).</li></ul></li><li><p><strong>Caching Complications</strong></p><ul><li>HTTPS traffic can’t be cached by some proxies or intermediate servers unless explicitly configured.</li></ul></li></ol><hr><h3 id="⚙️-summary-table" tabindex="-1">⚙️ <strong>Summary Table</strong> <a class="header-anchor" href="#⚙️-summary-table" aria-label="Permalink to “⚙️ Summary Table”">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>HTTP</th><th>HTTPS</th></tr></thead><tbody><tr><td>Security</td><td>No TLS transport protection</td><td>Encrypted with TLS</td></tr><tr><td>Data Integrity</td><td>Not guaranteed</td><td>Protected against tampering</td></tr><tr><td>Authentication</td><td>None</td><td>Verified via certificate</td></tr><tr><td>Performance</td><td>Depends on protocol/cache/network</td><td>Handshake/crypto costs and connection reuse must be measured</td></tr><tr><td>Application trust</td><td>Not established</td><td>Endpoint authentication does not establish benign content</td></tr><tr><td>Access to APIs</td><td>Limited</td><td>Required for modern web features</td></tr></tbody></table><hr><h3 id="💡-best-practice" tabindex="-1">💡 <strong>Best Practice</strong> <a class="header-anchor" href="#💡-best-practice" aria-label="Permalink to “💡 Best Practice”">​</a></h3><p>Always use HTTPS — the minor cost of setup and overhead is far outweighed by the security, trust, and compatibility benefits.</p><h2 id="tls1-3-handshake-separate-key-establishment-and-authentication" tabindex="-1">TLS1.3 handshake: separate key establishment and authentication <a class="header-anchor" href="#tls1-3-handshake-separate-key-establishment-and-authentication" aria-label="Permalink to “TLS1.3 handshake: separate key establishment and authentication”">​</a></h2><p>Version reference checked2026-10-22: RFC9846 (July2026) obsoletes RFC8446 while still specifying TLS1.3. The following is a conceptual certificate-authenticated handshake, not a cryptographic implementation recipe.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Purpose</th></tr></thead><tbody><tr><td>ClientHello / ServerHello</td><td>Negotiate parameters and key-establishment inputs, commonly ephemeral(E)DHE shares</td></tr><tr><td>Key schedule</td><td>Derive handshake/traffic secrets; the client does not encrypt a chosen session key with the certificate&#39;s RSA key</td></tr><tr><td>EncryptedExtensions / Certificate / CertificateVerify</td><td>Communicate parameters and certificate authentication; verify identity/trust and the transcript signature</td></tr><tr><td>Finished</td><td>Verify handshake transcript integrity before normal application use</td></tr><tr><td>Application records</td><td>Protect traffic using derived authenticated-encryption keys, e.g. AES-GCM or ChaCha20-Poly1305</td></tr></tbody></table><p>ECDSA is a signature algorithm, not encryption or key agreement. TLS1.3 does not use RSA key transport; RSA signatures are a different role. Resumption uses a PSK derived/associated with prior establishment to bootstrap new connection secrets, not simply reuse old traffic keys. PSK-only and asymmetric-exchange modes have different forward-secrecy properties. Optional0RTT early data has replay limitations and is not equivalent to ordinary confirmed application traffic.</p><p>A1.1/2 HTTPS example normally negotiates TLS over TCP, whereas HTTP3 uses QUIC&#39;s integrated TLS1.3 handshake/keying. A certificate signature algorithm alone does not identify every negotiated exchange/cipher property. Use maintained TLS/platform implementations and their deployment guidance; do not reproduce this table as home-grown security code.</p><h2 id="operational-boundaries-and-diagnosis" tabindex="-1">Operational boundaries and diagnosis <a class="header-anchor" href="#operational-boundaries-and-diagnosis" aria-label="Permalink to “Operational boundaries and diagnosis”">​</a></h2><p>Keep certificate renewal, chain/hostname/time validation, mixed content, redirects, HSTS and termination-hop policies explicit. Do not disable verification to make a failing request pass. A trusted terminating proxy can read traffic at that boundary; secure the next hop and logs according to the system design. HTTP caches still work over HTTPS at authorized endpoints/CDNs; authorization/cache-key/private response policy determines what may be shared. TLS does not fix XSS, CSRF, object authorization or leaked application secrets.</p><p>Official sources: <a href="https://www.rfc-editor.org/info/rfc9846/" target="_blank" rel="noreferrer">current TLS1.3 RFC9846</a>, <a href="https://www.rfc-editor.org/info/rfc8446/" target="_blank" rel="noreferrer">historical TLS1.3 RFC8446/status</a>, <a href="https://www.rfc-editor.org/info/rfc8470/" target="_blank" rel="noreferrer">early-data policy RFC8470</a>, <a href="https://www.rfc-editor.org/info/rfc9114/" target="_blank" rel="noreferrer">HTTP3 RFC9114</a>. Checked2026-10-22; review standards status and platform policy when deploying.</p><h2 id="separate-practice" tabindex="-1">Separate practice <a class="header-anchor" href="#separate-practice" aria-label="Permalink to “Separate practice”">​</a></h2><p>Use the <a href="./../../practice/engineering/security/HTTPS._Could_you_please_describe_advantages_and_disadvantages_of_this_protocol.html">focused acceptance and evidence requirements</a>. All learner practice remains outstanding.</p>',25)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
